(function () {
  var out = [];
  var fe = null;
  var host = null;
  var pick = "00000002-0000-0000-0000-000000000000";
  function step(key, fn) {
    try { out.push(key + "=" + fn()); } catch (e) { out.push(key + "=ERR " + String(e).replace(/[|=]/g, " ")); }
  }
  step("build", function () { return app.buildNumber; });
  step("frontend", function () { fe = app.getFrontend(); return fe ? "ok" : "null"; });
  step("addComp", function () {
    return fe.addCompToBatch("C:\\CRBK\\work\\fixtures\\CRT_fixture.aep", "C:\\CRBK\\work\\ame\\FullHD.epr", "C:\\CRBK\\work\\ame\\out_comp");
  });
  step("guids", function () {
    var g = fe.getDLItemsAtRoot("C:\\CRBK\\work\\fixtures\\CRT_fixture.aep");
    for (var i = 0; g && i < g.length; i++) {
      if (String(g[i]).toLowerCase().replace(/[{}]/g, "") === "00000002-0000-0000-0000-000000000000") { pick = String(g[i]); }
    }
    return g ? g.join(";") : "null";
  });
  step("addDL", function () {
    return fe.addDLToBatch("C:\\CRBK\\work\\fixtures\\CRT_fixture.aep", "H.264", "C:\\CRBK\\work\\ame\\FullHD.epr", pick, "C:\\CRBK\\work\\ame\\out_dl") ? "ok" : "null";
  });
  step("run", function () { host = app.getEncoderHost(); return host.runBatch(); });
  step("status", function () { return host.getBatchEncoderStatus(); });
  var f = new File("C:/CRBK/work/ame/reply.txt");
  f.encoding = "UTF-8";
  if (f.open("w")) { f.write(out.join("|")); f.close(); }
  return out.join("|");
})();
